import json,pathlib,hashlib,copy
p=pathlib.Path(__file__).resolve().parent; root=p.parent; pack=json.loads((p/'candidate_pack.json').read_text())[0];core=pack['authorial_core'];b=core['baseline_prompt_en']
b=b.replace('She wears a charcoal weatherproof coat over a cream knit top, straight dark trousers and practical ankle boots.','She wears a charcoal coat, cream knit top, dark trousers and ankle boots.')
b=b.replace('Her torso turns a little toward the camera, with a quiet attentive expression.','Her torso turns slightly toward the camera.')
b=b.replace('Keep the ordinary infrastructure legible across the image, with believable material surfaces and continuous geometry. ','').replace('The result should feel like a candid photograph made at an actual working transit stop.','')
infra=['a drain cover fits flush within the walking surface','a service pipe follows the wall on visible supports','the fixtures leave a continuous passage through the space']
