joint='These material responses and the depth of focus belong to the same continuous landing-to-shelter view.'
prompt=' '.join((b+' At the landing, '+infra[0]+'; along the retaining wall, '+infra[1]+'; '+infra[2]+'. '+mat+' '+foc+' '+joint+' Frame horizontally at chest height with a 35mm lens, placing her just right of center.').split())
comp=json.loads((root/'composed_prompt.json').read_text());comp.update(pack_id=pack['pack_id'],prompt_en=prompt,negative_en=pack['negative_en'],chosen_candidate_ids=['bundle:rbb_surface_focus'],chosen_visual_concept_ids=['visual-concept:rb_infrastructure_attachment'])
comp['candidate_interpretations']=[{'candidate_id':'bundle:rbb_surface_focus','artistic_interpretation':'Resolve the shelter concrete, steel and glass as distinct surfaces while the woman stays legible within receding transit architecture.','transformation':'Tie surface reflectance to the particular shelter base and let uphill apartment detail diminish with distance within the same view.','prompt_evidence':mat,'component_evidence':{'rb_material_response_contrast_component':mat,'rb_readable_environment_focus_component':foc},'relation_evidence':{'rbb_surface_focus_joint':joint}}]
comp['visual_obligation_evidence']={'rb_infrastructure_attachment':{f'component_{i+1}_phrase':v for i,v in enumerate(infra)}}
comp['authorial_core_binding']['authorial_decisions']=[{'dimension':'camera','decision':foc,'rationale':'Control depth of focus so face, contact and transit context stay assessable without uniform sharpness.'},{'dimension':'material','decision':mat,'rationale':'Resolve the three existing shelter materials through different responses to the same overcast sky.'}]
comp['semantic_clarification_decisions']=[]
for r in pack['semantic_clarification']['candidates']:
 apply=r['required_in_final_prompt'] or r.get('profile_id')=='rb_infrastructure_attachment'
 comp['semantic_clarification_decisions'].append({'clarification_id':r['id'],'decision':'applied' if apply else 'rejected','rationale':'Preserve the frozen transit scene and clarify its already present ordinary infrastructure.' if apply else 'This optional body, behavioral, or rendering concept is outside the frozen natural transit scene.','prompt_evidence':infra[0] if r.get('profile_id')=='rb_infrastructure_attachment' else 'one adult woman at a terraced hillside bus interchange on an overcast morning after rain' if apply else ''})
review=copy.deepcopy(json.loads((root/'embodiment_review.json').read_text()));review.update(provenance='agent_postcomposition',prompt_sha256=hashlib.sha256(prompt.encode()).hexdigest(),summary='Rechecked the final prompt after adding infrastructure and optical/material clauses. Both arms keep separate targets, both boots share the broad landing, the service pipe lies along the retaining wall and leaves the passage clear, and chest-height full-figure view preserves contact visibility.')
comp['embodiment_review']={'source_contract_sha256':pack['embodiment_preflight']['canonical_sha256'],'review':review}
(p/'composed_prompt.json').write_text(json.dumps(comp,ensure_ascii=False,indent=2)+'\n');(p/'final_prompt.txt').write_text(prompt+'\n')
